-- 2501: never email the made-up addresses Momence invents for clients who signed up without one
-- (@autogenerated.momence.com). Imported clients with one get a staff note ("Needs a real email").
-- Both outboxes mark such a message as skipped when it is queued, so the senders never see it.
-- Changing the client's email to a real one later makes everything flow again.

create or replace function app.skip_placeholder_notification() returns trigger
language plpgsql as $$
begin
  if lower(coalesce(new.to_email, '')) like '%@autogenerated.momence.com' and new.sent_at is null then
    new.sent_at := now();
    new.error := 'Skipped: made-up Momence address, needs a real email';
  end if;
  return new;
end $$;
drop trigger if exists skip_placeholder_notification on public.notifications;
create trigger skip_placeholder_notification before insert on public.notifications
  for each row execute function app.skip_placeholder_notification();

create or replace function app.skip_placeholder_marketing() returns trigger
language plpgsql as $$
begin
  if new.channel = 'email' and lower(coalesce(new.to_address, '')) like '%@autogenerated.momence.com' and new.status = 'queued' then
    new.status := 'skipped';
    new.error := 'Skipped: made-up Momence address, needs a real email';
  end if;
  return new;
end $$;
drop trigger if exists skip_placeholder_marketing on public.marketing_messages;
create trigger skip_placeholder_marketing before insert on public.marketing_messages
  for each row execute function app.skip_placeholder_marketing();
